#!/usr/bin/python

import sys

# Tokens are the same as in 3rdparty/sidid/sidid.c config parser
ANY = 256
AND = 257
END = 258

def parse(path):
  players = []
  signatures = []
  current = []
  with open(path, 'r') as cfg:
    for token in cfg.read().split():
      if token == '??':
        current.append(ANY)
      elif token.upper() == 'AND':
        current.append(AND)
      elif token.upper() == 'END':
        # empty signatures are ignored by original parser
        if current:
          signatures.append((len(players) - 1, current + [END]))
        current = []
      elif len(token) == 2 and all(c in '0123456789abcdefABCDEF' for c in token):
        current.append(int(token, 16))
      else:
        players.append(token.replace('_', ' '))
        current = []
  return players, signatures

def dump(players, signatures):
  print('// Generated by mksidid.py from 3rdparty/sidid/sidid.cfg')
  print('// Players={} Signatures={}'.format(len(players), len(signatures)))
  print('constexpr const char* PLAYERS[] = {')
  for name in players:
    print('    "{}",'.format(name.replace('\\', '\\\\').replace('"', '\\"')))
  print('};')
  print('constexpr uint16_t ANY = {};'.format(ANY))
  print('constexpr uint16_t AND = {};'.format(AND))
  print('constexpr uint16_t END = {};'.format(END))
  print('constexpr uint16_t TOKENS[] = {')
  offsets = []
  offset = 0
  for _, tokens in signatures:
    offsets.append(offset)
    offset += len(tokens)
    print('    ' + ','.join(str(t) for t in tokens) + ',')
  print('};')
  print('constexpr Signature SIGNATURES[] = {')
  for (player, _), offset in zip(signatures, offsets):
    print('    {{{}, {}}},'.format(player, offset))
  print('};')

if __name__ == '__main__':
  dump(*parse(sys.argv[1]))
